      "translit": "Qul inna rabbī yabsuṭu r-rizqa liman yashāʾu min ʿibādihī wayaqdiru lahū wamā anfaqtum min shayʾin fahuwa yukhlifuhū wahuwa khayru r-rāziqīn",
